nodes.structuredOutputSchema:
{
  "type": "object",
  "properties": {
    "docket": {
      "type": "string",
      "description": "NN-NN-LNG 형식 도켓 번호만"
    },
    "stage": {
      "type": "string",
      "description": "pre_fid, construction, commissioning, operating 중 하나"
    },
    "operating": {
      "type": "boolean",
      "description": "true 또는 false"
    },
    "online_month": {
      "type": "string",
      "description": "YYYY-MM 또는 빈 문자열"
    },
    "slip_months": {
      "type": "integer",
      "description": "정수"
    },
    "kr_buyers": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "회사명 목록, 없으면 빈 목록"
    },
    "kr_mtpa": {
      "type": "number",
      "description": "숫자, 없으면 0"
    },
    "uncontracted_mtpa": {
      "type": "number",
      "description": "숫자, 없으면 0"
    },
    "config_status": {
      "type": "string",
      "description": "반영 또는 검토 필요"
    },
    "reason": {
      "type": "string",
      "description": "한국어 1~2문장"
    }
  },
  "required": [
    "docket",
    "stage",
    "operating",
    "online_month",
    "slip_months",
    "kr_buyers",
    "kr_mtpa",
    "uncontracted_mtpa",
    "config_status",
    "reason"
  ],
  "additionalProperties": false
}
